import React from "react";

export function ProgressBar({ value = 68 }: { value?: number }) {
  return (
    <div className="w-full space-y-1.5">
      <div className="flex justify-between text-xs font-mono"><span>Progress</span><span>{value}%</span></div>
      <div className="h-2 rounded-full bg-muted overflow-hidden"><div style={{ width: `${value}%` }} className="h-full bg-primary rounded-full" /></div>
    </div>
  );
}
